// ServerInterface represents all server handlers.
type ServerInterface interface {

	// (POST /v1/ad-hoc/register)
	RegisterInvocation(w http.ResponseWriter, r *http.Request)

	// (POST /v1/capabilities)
	IssueCapability(w http.ResponseWriter, r *http.Request)

	// (POST /v1/check)
	Check(w http.ResponseWriter, r *http.Request)

	// (GET /v1/events)
	Events(w http.ResponseWriter, r *http.Request, params EventsParams)

	// (GET /v1/health)
	Health(w http.ResponseWriter, r *http.Request, params HealthParams)

	// (POST /v1/leases)
	AcquireLease(w http.ResponseWriter, r *http.Request)

	// (POST /v1/prepare)
	Prepare(w http.ResponseWriter, r *http.Request)

	// (POST /v1/register)
	Register(w http.ResponseWriter, r *http.Request)

	// (POST /v1/renew)
	Renew(w http.ResponseWriter, r *http.Request)

	// (GET /v1/status)
	Status(w http.ResponseWriter, r *http.Request)

	// (POST /v1/unregister)
	Unregister(w http.ResponseWriter, r *http.Request)
}

// ServerInterfaceWrapper converts contexts to parameters.
type ServerInterfaceWrapper struct {
	Handler            ServerInterface
	HandlerMiddlewares []MiddlewareFunc
	ErrorHandlerFunc   func(w http.ResponseWriter, r *http.Request, err error)
}

type MiddlewareFunc func(http.Handler) http.Handler

// RegisterInvocation operation middleware
func (siw *ServerInterfaceWrapper) RegisterInvocation(w http.ResponseWriter, r *http.Request) {

	handler := http.Handler(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		siw.Handler.RegisterInvocation(w, r)
	}))

	for _, middleware := range siw.HandlerMiddlewares {
		handler = middleware(handler)
	}

	handler.ServeHTTP(w, r)
}

